from clarifai.rest import ClarifaiApp

app = ClarifaiApp(api_key='your_clarifai_api_key')

def check_text_safety(text, threshold=0.8):
    model = app.public_models.moderation
    response = model.predict(text_inputs=[text])
    if response['status']['code'] == 10000:
        concepts = response['outputs'][0]['data']['concepts']
        for concept in concepts:
            if concept['name'] =='sexual' and concept['value'] > threshold:
                return False
            elif concept['name'] == 'violence' and concept['value'] > threshold:
                return False
            elif concept['name'] == 'hate' and concept['value'] > threshold:
                return False
        return True
    return False
